```sql
SELECT T2.title ,  max(T3.stars) ,  T1.director FROM Ratings AS T1 JOIN Movie AS T2 ON T1.mID  =  T2.mID JOIN Rating AS T3 ON T1.rID  =  T3.rID WHERE T3.stars  =  ( SELECT MAX(stars) FROM Ratings AS T1 JOIN Movie AS T2 ON T1.mID  =  T2.mID WHERE director  !=  NULL ) GROUP BY T1.director ORDER BY T2.stars DESC;
```

